"""Summaries, pedagogical resources and the course chat of the summaries module."""

from django.conf import settings
from django.db import models

from courses.models import Course


class Summary(models.Model):
    """A course summary, written by hand or generated by Gemini."""

    class Source(models.TextChoices):
        MANUAL = "manual", "Written manually"
        AI = "ai", "Generated by AI"

    course = models.ForeignKey(Course, on_delete=models.CASCADE, related_name="summaries")
    author = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="summaries"
    )
    title = models.CharField(max_length=200)
    # Plain text: "## " starts a section title and "- " a bullet point.
    content = models.TextField()
    # Key notions of the course: [{"term": "...", "definition": "..."}]
    key_concepts = models.JSONField(default=list, blank=True)
    language = models.CharField(max_length=5, default="en")
    source = models.CharField(max_length=10, choices=Source.choices, default=Source.MANUAL)
    ai_model = models.CharField(max_length=80, blank=True)
    # Explanatory picture: the prompt written by Gemini and the generated image.
    illustration = models.ImageField(upload_to="summaries/illustrations/", blank=True)
    illustration_prompt = models.TextField(blank=True)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ["-updated_at"]
        verbose_name_plural = "summaries"

    def __str__(self):
        return self.title


class Resource(models.Model):
    """A pedagogical resource of a course: a web link or a file."""

    class Kind(models.TextChoices):
        LINK = "link", "Web link"
        FILE = "file", "File"

    course = models.ForeignKey(Course, on_delete=models.CASCADE, related_name="resources")
    author = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="resources"
    )
    title = models.CharField(max_length=200)
    description = models.TextField(blank=True)
    kind = models.CharField(max_length=10, choices=Kind.choices, default=Kind.LINK)
    url = models.URLField(max_length=500, blank=True)
    file = models.FileField(upload_to="summaries/resources/", blank=True)
    file_name = models.CharField(max_length=255, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ["-updated_at"]

    def __str__(self):
        return self.title


class ChatMessage(models.Model):
    """One question asked to the course assistant and Gemini's answer."""

    summary = models.ForeignKey(Summary, on_delete=models.CASCADE, related_name="chat_messages")
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="summary_chat_messages"
    )
    question = models.TextField()
    answer = models.TextField()
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        ordering = ["created_at", "id"]
